def restore_checkpoint(self, checkpoint):
	if hasattr(self.trainer, "restore_checkpoint"):
		self.trainer.restore_checkpoint(checkpoint)
		return

	if hasattr(self.trainer, "restore_backend_state"):
		self.trainer.restore_backend_state(checkpoint.metadata)
		return

	raise AttributeError("trainer does not support checkpoint restore")
